use super::*;
use semio_s_artifact_energy_model_native_mutations::owned::{OwnedRowPath,OwnedRowPreparation};
#[path="../../../../📸️snapshot/🧳️state/🧪️tests/🧰️helpers/🦀️.rs"]mod helpers;
use helpers::{corpus,receive,source,grant,observe,drain,central_fragment,project_record,denied_axes};
use crate::snapshot::original::EnergyModelSnapshot;
#[test]fn original_aperture_polygon_bounds_each_host_edge_and_point_preserves_exact_inverse_and_every_cancelled_source(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();assert_eq!(law["toleranceM"].as_f64().unwrap(),crate::model::FENESTRATION_PLANE_TOLERANCE_M);for case in law["cases"].as_array().unwrap(){let mut doc:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();doc=doc["document"].take();doc["model"]=corpus()["model"].clone();doc["model"]["fenestrations"]=serde_json::json!([law["original"]]);doc["model"]["surfaces"]=serde_json::json!([law["host"]]);let original=source(helpers::receive_retained::<EnergyModelSnapshot>(&doc));let mut values=helpers::receive_retained::<Vec<[f64;3]>>(&case["value"]);if let Some(at)=case["nonfiniteAt"].as_array(){values[at[0].as_u64().unwrap()as usize][at[1].as_u64().unwrap()as usize]=f64::NAN;}let input=source(values);let key=source(case["id"].as_u64().unwrap()as u32);
 for cut in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize))){let mut owner=OwnedRowPreparation::<__ReplaceFenestrationVerticesNativeRowPath>::new();for _ in 0..cut.unwrap_or(20000){if owner.ready(){break;}let d=owner.demand(input.borrow(),key.borrow(),original.borrow(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.advance(input.borrow(),key.borrow(),original.borrow(),4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.demand(input.borrow(),key.borrow(),original.borrow(),4096).unwrap(),d);}let(s,h)=observe(||owner.advance(input.borrow(),key.borrow(),original.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}
 if cut.is_none(){assert!(owner.ready());assert_eq!(owner.outcome().unwrap().as_str(),case["outcome"].as_str().unwrap());if case["outcome"]=="changed"{let((diff,p),h)=observe(||owner.take(grant(owner.take_demand().unwrap())).unwrap().unwrap());assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));let diff=source(diff);let mut post=project_record(original.borrow());assert!(central_fragment(&diff,original.borrow(),&mut post));let row=post.model.geometry.get().fenestrations.get(0).unwrap();assert_eq!(row.vertices_m.get(),input.borrow().get());assert_eq!(post.model.materials.identity(),original.borrow().get().model.materials.identity());assert_eq!(row.name.identity(),original.borrow().get().model.geometry.get().fenestrations.get(0).unwrap().name.identity());for _ in 0..20000{if owner.inverse_ready(){break;}let d=owner.inverse_demand(4096).unwrap();let(s,h)=observe(||owner.inverse(4096,grant(d)).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.inverse_ready());let((inverse,p),h)=observe(||owner.take_inverse(grant(owner.take_inverse_demand().unwrap())).unwrap().unwrap());assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(inverse,receive::<Vec<[f64;3]>>(&law["original"]["vertices_m"]));drain(inverse);drain(post);drain(diff);}}
 owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demand(4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.close_step(denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.close_demand(4096).unwrap(),d);}let(s,h)=observe(||owner.close_step(g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));}drain(key);drain(input);drain(original);}
}
